void testDeprecated_handlerTriggeredForDeprecatedOptions() {
    TestSetup ts = assertDoesNotThrow(() -> setupTestDeprecated(),
            "Unexpected ParseException during test");
    assertTrue(ts.handler.contains(ts.opt1), "Handler should contain deprecated option d1");
    assertTrue(ts.handler.contains(ts.opt2), "Handler should contain deprecated option d2");
}

@Test
void testDeprecated_handlerNotTriggeredForNonDeprecatedOption() {
    TestSetup ts = assertDoesNotThrow(() -> setupTestDeprecated(),
            "Unexpected ParseException during test");
    assertTrue(ts.cl.hasOption(ts.opt1.getOpt()), "Option -d1 should be present");
    assertTrue(ts.cl.hasOption(ts.opt2.getOpt()), "Option -d2 should be present");
    assertTrue(ts.cl.hasOption(ts.opt3.getOpt()), "Option -a should be present");
    assertFalse(ts.handler.contains(ts.opt3), "Handler should not contain non‑deprecated option a");
}

private TestSetup setupTestDeprecated() throws ParseException {
    Set<Option> handler = new HashSet<>();
    DefaultParser parser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    Option opt1 = Option.builder().option("d1").deprecated().build();
    Option opt2 = Option.builder().option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();
    Option opt3 = Option.builder().option("a").build();

    CommandLine cl = parser.parse(new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3),
            new String[] {"-d1", "-d2", "-a"});

    return new TestSetup(handler, cl, opt1, opt2, opt3);
}

private static class TestSetup {
    final Set<Option> handler;
    final CommandLine cl;
    final Option opt1;
    final Option opt2;
    final Option opt3;

    TestSetup(Set<Option> handler, CommandLine cl, Option opt1, Option opt2, Option opt3) {
        this.handler = handler;
        this.cl = cl;
        this.opt1 = opt1;
        this.opt2 = opt2;
        this.opt3 = opt3;
    }
}

