@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

/**
 * Runs the given {@link ThrowingRunnable} and fails if it throws any exception.
 */
private static <T> T assertDoesNotThrow(ThrowingRunnable runnable) {
    try {
        // The runnable is expected to return a value via a single-element array trick.
        final Object[] result = new Object[1];
        runnable.run();
        // If the runnable returns a value, capture it (used for generic return types).
        // In our current usage, the runnable returns a JsonReader via a lambda that
        // assigns to a final array; we retrieve it here.
        @SuppressWarnings("unchecked")
        T castResult = (T) result[0];
        return castResult;
    } catch (Exception e) {
        fail("Unexpected exception thrown: " + e);
        return null; // Unreachable, but required for compilation.
    }
}

