/**
 * Validates that a malformed JSON string causes {@link MalformedJsonException} at the expected
 * location both when reading normally and when skipping values.
 *
 * @param message the expected exception message (without the troubleshooting URL suffix)
 * @param json    the malformed JSON document
 */
private static void testFailWithPosition(String message, String json) throws IOException {
  // Validate that it works reading the string normally.
  JsonReader reader1 = new JsonReader(reader(json));
  reader1.setStrictness(Strictness.LENIENT);
  reader1.beginArray();
  String unused1 = reader1.nextString();
  var e = assertThrows(
      "Expect MalformedJsonException when peeking after reading first element",
      MalformedJsonException.class,
      () -> reader1.peek());
  assertThat(e)
      .hasMessageThat()
      .isEqualTo(
          message
              + "\n"
              + "See https://github.com/google/gson/blob/main/Troubleshooting.md#malformed-json");

  // Also validate that it works when skipping.
  JsonReader reader2 = new JsonReader(reader(json));
  reader2.setStrictness(Strictness.LENIENT);
  reader2.beginArray();
  reader2.skipValue();
  e = assertThrows(
      "Expect MalformedJsonException when peeking after skipping a value",
      MalformedJsonException.class,
      () -> reader2.peek());
  assertThat(e)
      .hasMessageThat()
      .isEqualTo(
          message
              + "\n"
              + "See https://github.com/google/gson/blob/main/Troubleshooting.md#malformed-json");
}

