 * as an {@link AssertionError} with the provided message.
 *
 * @param supplier the operation to execute
 * @param message  the failure message if an exception is thrown
 * @param <T>      the type of the result
 * @return the result of the supplier if no exception occurs
 */
private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier, String message) {
    try {
        return supplier.get();
    } catch (Throwable t) {
        throw new AssertionError(message, t);
    }
}

/**
 * Functional interface similar to {@link java.util.function.Supplier} but allows
 * a checked exception to be thrown.
 *
 * @param <T> the type of results supplied by this supplier
 */
@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

