@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

/**
 * Executes the supplied operation and fails the test if any exception is thrown.
 *
 * @param supplier the operation to execute
 * @param message  description used when the operation throws an unexpected exception
 * @param <T>      the type of the result returned by the supplier
 * @return the result of the supplier if no exception is thrown
 */
private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier, String message) {
    try {
        return supplier.get();
    } catch (Throwable t) {
        fail(message + ": " + t);
        return null; // unreachable, but required for compilation
    }
}

