/**
 * Mimics JUnit 5's assertDoesNotThrow for environments using JUnit 4.
 */
private static void assertDoesNotThrow(ThrowingRunnable runnable) {
    try {
        runnable.run();
    } catch (Throwable t) {
        fail("Unexpected exception: " + t);
    }
}

/**
 * Creates a {@link JsonWriter} that has been closed, asserting that no IOException is thrown
 * during the setup.
