private JsonWriter createClosedWriter() {
    final JsonWriter[] writerHolder = new JsonWriter[1];
    assertDoesNotThrow(() -> {
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.beginArray();
        writer.endArray();
        writer.close();
        writerHolder[0] = writer;
